extra_css:
/* theme: citypop-dusk (2026-10-27) */
:root,:root:not(x){--bg:#17143a;--fg:#f4efff;--muted:#b7b3d9;--line:#353070;--card:#211d4d;--soft:#2a2560;--accent:#ff7eb6;--accent2:#ffb15c}
@media (prefers-color-scheme:dark){:root{--bg:#17143a;--fg:#f4efff;--muted:#b7b3d9;--line:#353070;--card:#211d4d;--soft:#2a2560;--accent:#ff7eb6;--accent2:#ffb15c}}
body{background:linear-gradient(180deg,#2b1f5c 0,#17143a 420px) no-repeat,var(--bg)}
header{background:linear-gradient(90deg,#ff8a5c22,#ff7eb622,#5cc8d622),#17143a;border-bottom:0;box-shadow:0 3px 0 #ffb15c,0 6px 0 #ff7eb6,0 9px 0 #8e6bff}
.wrap>.layout{padding-top:34px}
.logo,.hero h1,article h1,.sec-h,article h2,.picks-h,.next-h,aside .box-h{font-family:"RocknRoll One","Hiragino Sans",sans-serif;font-weight:400}
.logo{color:#fff}.logo span{background:linear-gradient(90deg,#ffb15c,#ff7eb6);-webkit-background-clip:text;background-clip:text;color:transparent}
.gnav a{background:#2a2560;color:#f4efff;border-radius:6px}
.gnav a:hover,.gnav a.on{background:linear-gradient(90deg,#ffb15c,#ff7eb6);color:#17143a}
.hero-img{border-radius:6px;box-shadow:0 10px 30px #ff7eb633}
.sec-h{border-bottom:0;background:linear-gradient(90deg,#ffb15c,#ff7eb6,#8e6bff) bottom/100% 4px no-repeat}
.card{border:0;border-radius:4px;background:#211d4d;box-shadow:0 0 0 1px #353070}
.thumb{border-radius:4px 4px 0 0}
.card:hover{box-shadow:0 0 0 2px #ff7eb6,8px 8px 0 #ffb15c55}
.tag{background:#5cc8d6;color:#17143a;font-weight:700;border-radius:4px}
article h2{background:#211d4d;border-left:0;border-radius:4px;padding:10px 14px 10px 30px;position:relative}
article h2::before{content:"";position:absolute;left:10px;top:10px;bottom:10px;width:10px;background:linear-gradient(180deg,#ffb15c 0 33%,#ff7eb6 33% 66%,#8e6bff 66%)}
article h3{border-bottom:2px solid #5cc8d6}
.toc{border-top:4px solid #ffb15c}
.note{border-left-color:#5cc8d6}
.picks{border:2px solid #ff7eb6;border-radius:6px}
.picks-h::before{content:"♪ ";color:#ffb15c}
.next{border-color:#ffb15c;background:#211d4d;border-radius:6px}
.avatar{background:radial-gradient(circle,#17143a 0 18%,#ff7eb6 19% 100%)}
aside .box-h{border-bottom:3px solid #ff7eb6}
.mini b{background:#ffb15c;color:#17143a}
th{background:#2a2560}
footer{background:#100d2c;border-top:0;box-shadow:0 -3px 0 #8e6bff,0 -6px 0 #ff7eb6,0 -9px 0 #ffb15c}
